const ACTOR_STORAGE_KEY = 'certAdmin.actorId';

export function getStoredActorId(): string | null {
  try {
    return localStorage.getItem(ACTOR_STORAGE_KEY);
  } catch {
    return null;
  }
}

export function storeActorId(id: string | null): void {
  try {
    if (id === null) {
      localStorage.removeItem(ACTOR_STORAGE_KEY);
    } else {
      localStorage.setItem(ACTOR_STORAGE_KEY, id);
    }
  } catch {
    // Ignore storage failures (e.g. private browsing).
  }
}

export class ApiError extends Error {
  status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

export function errorMessage(err: unknown): string {
  if (err instanceof ApiError) return err.message;
  if (err instanceof Error) return err.message;
  return 'Unexpected error';
}

async function readError(res: Response): Promise<string> {
  try {
    const data = (await res.json()) as { error?: string };
    if (data && typeof data.error === 'string') return data.error;
  } catch {
    // fall through to a generic message
  }
  return `Request failed with status ${res.status}`;
}

interface FetchOptions {
  /** Defaults to true. Set false only for the actor list bootstrap request. */
  attachActor?: boolean;
}

async function rawFetch(
  path: string,
  init: RequestInit = {},
  opts: FetchOptions = {},
): Promise<Response> {
  const headers = new Headers(init.headers);
  if (opts.attachActor !== false) {
    const actorId = getStoredActorId();
    if (actorId) {
      headers.set('X-Actor-Id', actorId);
    }
  }
  return fetch(path, { ...init, headers });
}

async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await rawFetch(path, init);
  if (!res.ok) {
    throw new ApiError(res.status, await readError(res));
  }
  return (await res.json()) as T;
}

// ---- Types ----

export interface Actor {
  email: string;
  tenant: string;
}

export interface Course {
  id: number;
  title: string;
}

export interface CertificateListItem {
  id: number;
  serialNumber: string;
  learnerName: string;
  courseTitle: string;
  status: string;
  issuedDateLocal: string;
}

export interface CertificateList {
  items: CertificateListItem[];
  total: number;
  page: number;
  pageSize: number;
}

export interface CertificateDetail {
  id: number;
  serialNumber: string;
  learnerName: string;
  courseTitle: string;
  status: string;
  issuedAtLocal: string;
  revokedAtLocal: string | null;
}

export type OutcomeStatus = 'issued' | 'skipped' | 'failed';

export interface BulkIssueOutcome {
  learnerId: number;
  learnerName: string;
  status: OutcomeStatus;
  reason: string | null;
}

export interface BulkIssueSummary {
  issued: number;
  skipped: number;
  failed: number;
}

export interface BulkIssueResult {
  courseId: number;
  outcomes: BulkIssueOutcome[];
  summary: BulkIssueSummary;
}

export interface ListParams {
  search: string;
  sort: string;
  order: string;
  page: number;
  pageSize: number;
}

// ---- API calls ----

export async function fetchActors(): Promise<Actor[]> {
  const res = await rawFetch('/api/actors', {}, { attachActor: false });
  if (!res.ok) {
    throw new ApiError(res.status, await readError(res));
  }
  const data = (await res.json()) as { actors: Actor[] };
  return data.actors;
}

export async function fetchCourses(): Promise<Course[]> {
  const data = await apiFetch<{ courses: Course[] }>('/api/courses');
  return data.courses;
}

export async function fetchCertificates(params: ListParams): Promise<CertificateList> {
  const q = new URLSearchParams();
  if (params.search) q.set('search', params.search);
  if (params.sort) q.set('sort', params.sort);
  if (params.order) q.set('order', params.order);
  q.set('page', String(params.page));
  q.set('pageSize', String(params.pageSize));
  return apiFetch<CertificateList>(`/api/certificates?${q.toString()}`);
}

export async function fetchCertificate(id: number): Promise<CertificateDetail> {
  return apiFetch<CertificateDetail>(`/api/certificates/${id}`);
}

export async function bulkIssue(
  courseId: number,
  idempotencyKey: string,
): Promise<BulkIssueResult> {
  return apiFetch<BulkIssueResult>('/api/certificates/bulk-issue', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Idempotency-Key': idempotencyKey,
    },
    body: JSON.stringify({ courseId }),
  });
}

export async function revokeCertificate(id: number): Promise<{ id: number; status: string }> {
  return apiFetch<{ id: number; status: string }>(`/api/certificates/${id}/revoke`, {
    method: 'POST',
  });
}

export async function exportCsv(search: string, sort: string, order: string): Promise<void> {
  const q = new URLSearchParams();
  if (search) q.set('search', search);
  if (sort) q.set('sort', sort);
  if (order) q.set('order', order);
  const qs = q.toString();
  const path = `/api/export/certificates.csv${qs ? `?${qs}` : ''}`;

  const res = await rawFetch(path);
  if (!res.ok) {
    throw new ApiError(res.status, await readError(res));
  }

  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = 'certificates.csv';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

import { createRoot } from 'react-dom/client';
import App from './App';
import './styles.css';

const container = document.getElementById('root');
if (!container) {
  throw new Error('Root element #root not found');
}

createRoot(container).render(<App />);

import { useEffect, useState } from 'react';
import {
  Actor,
  errorMessage,
  fetchActors,
  getStoredActorId,
  storeActorId,
} from './api';
import { ActorSwitcher } from './components/ActorSwitcher';
import { BulkIssue } from './components/BulkIssue';
import { CertificateDetail } from './components/CertificateDetail';
import { CertificateList } from './components/CertificateList';

export default function App() {
  const [actors, setActors] = useState<Actor[]>([]);
  const [actorsLoading, setActorsLoading] = useState(true);
  const [actorsError, setActorsError] = useState<string | null>(null);
  const [actorId, setActorId] = useState<string | null>(null);
  const [selectedCertificateId, setSelectedCertificateId] = useState<number | null>(null);
  const [listRefreshToken, setListRefreshToken] = useState(0);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const list = await fetchActors();
        if (cancelled) return;
        setActors(list);
        setActorsError(null);

        const stored = getStoredActorId();
        const next =
          stored && list.some((actor) => actor.email === stored)
            ? stored
            : (list[0]?.email ?? null);
        storeActorId(next);
        setActorId(next);
      } catch (err) {
        if (!cancelled) setActorsError(errorMessage(err));
      } finally {
        if (!cancelled) setActorsLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const refreshList = () => setListRefreshToken((n) => n + 1);

  const handleChangeActor = (email: string) => {
    storeActorId(email);
    setActorId(email);
    setSelectedCertificateId(null);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Certificate Admin Console</h1>
        <ActorSwitcher
          actors={actors}
          actorId={actorId}
          loading={actorsLoading}
          error={actorsError}
          onChange={handleChangeActor}
        />
      </header>

      {actorId === null ? (
        <div className="placeholder">
          <p>Select an actor to continue.</p>
        </div>
      ) : (
        <main className="app-main">
          <section className="panel">
            <BulkIssue actorId={actorId} onIssued={refreshList} />
          </section>
          <section className="panel">
            <CertificateList
              actorId={actorId}
              refreshToken={listRefreshToken}
              onSelectCertificate={setSelectedCertificateId}
            />
          </section>
        </main>
      )}

      {selectedCertificateId !== null && (
        <CertificateDetail
          certificateId={selectedCertificateId}
          onClose={() => setSelectedCertificateId(null)}
          onRevoked={() => {
            setSelectedCertificateId(null);
            refreshList();
          }}
        />
      )}
    </div>
  );
}

import { Actor } from '../api';

interface Props {
  actors: Actor[];
  actorId: string | null;
  loading: boolean;
  error: string | null;
  onChange: (email: string) => void;
}

export function ActorSwitcher({ actors, actorId, loading, error, onChange }: Props) {
  if (loading) {
    return <span className="actor-loading">Loading actors…</span>;
  }

  if (error) {
    return (
      <span className="actor-error" role="alert">
        Actors unavailable: {error}
      </span>
    );
  }

  return (
    <label className="actor-switcher">
      <span className="actor-label">Actor</span>
      <select value={actorId ?? ''} onChange={(e) => onChange(e.target.value)}>
        <option value="" disabled>
          Select an actor
        </option>
        {actors.map((actor) => (
          <option key={actor.email} value={actor.email}>
            {actor.email} ({actor.tenant})
          </option>
        ))}
      </select>
    </label>
  );
}

import { useEffect, useState } from 'react';
import {
  CertificateListItem,
  errorMessage,
  exportCsv,
  fetchCertificates,
} from '../api';

interface Props {
  actorId: string;
  refreshToken: number;
  onSelectCertificate: (id: number) => void;
}

const SORT_OPTIONS: { value: string; label: string }[] = [
  { value: 'issueDate', label: 'Issue date' },
  { value: 'learnerName', label: 'Learner name' },
  { value: 'serial', label: 'Serial number' },
  { value: 'courseTitle', label: 'Course' },
];

export function CertificateList({ actorId, refreshToken, onSelectCertificate }: Props) {
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState('issueDate');
  const [order, setOrder] = useState<'asc' | 'desc'>('desc');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const [items, setItems] = useState<CertificateListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [retryToken, setRetryToken] = useState(0);

  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState<string | null>(null);

  // Debounce the search input before it hits the list query.
  useEffect(() => {
    const timer = setTimeout(() => {
      setSearch(searchInput);
      setPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchInput]);

  useEffect(() => {
    if (!actorId) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchCertificates({ search, sort, order, page, pageSize })
      .then((data) => {
        if (cancelled) return;
        setItems(data.items);
        setTotal(data.total);
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(errorMessage(err));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [actorId, refreshToken, retryToken, search, sort, order, page, pageSize]);

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  const handleExport = async () => {
    setExporting(true);
    setExportError(null);
    try {
      await exportCsv(search, sort, order);
    } catch (err) {
      setExportError(errorMessage(err));
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className="certificate-list">
      <div className="list-header">
        <h2>Certificates</h2>
        <button className="btn" onClick={handleExport} disabled={exporting}>
          {exporting ? 'Exporting…' : 'Export CSV'}
        </button>
      </div>

      <div className="controls">
        <input
          type="search"
          className="search-input"
          placeholder="Search learner name or serial"
          value={searchInput}
          onChange={(e) => setSearchInput(e.target.value)}
        />
        <select
          value={sort}
          onChange={(e) => {
            setSort(e.target.value);
            setPage(1);
          }}
        >
          {SORT_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              Sort: {option.label}
            </option>
          ))}
        </select>
        <select
          value={order}
          onChange={(e) => {
            setOrder(e.target.value as 'asc' | 'desc');
            setPage(1);
          }}
        >
          <option value="desc">Descending</option>
          <option value="asc">Ascending</option>
        </select>
        <select
          value={pageSize}
          onChange={(e) => {
            setPageSize(Number(e.target.value));
            setPage(1);
          }}
        >
          <option value={20}>20 / page</option>
          <option value={50}>50 / page</option>
          <option value={100}>100 / page</option>
        </select>
      </div>

      {exportError && (
        <div className="error-banner" role="alert">
          Export failed: {exportError}
        </div>
      )}

      {loading ? (
        <div className="state">Loading certificates…</div>
      ) : error ? (
        <div className="state error" role="alert">
          <p>{error}</p>
          <button className="btn" onClick={() => setRetryToken((n) => n + 1)}>
            Retry
          </button>
        </div>
      ) : items.length === 0 ? (
        <div className="state">No certificates found.</div>
      ) : (
        <>
          <table className="cert-table">
            <thead>
              <tr>
                <th>Serial</th>
                <th>Learner</th>
                <th>Course</th>
                <th>Status</th>
                <th>Issued (local)</th>
              </tr>
            </thead>
            <tbody>
              {items.map((cert) => (
                <tr
                  key={cert.id}
                  className="clickable"
                  onClick={() => onSelectCertificate(cert.id)}
                >
                  <td>{cert.serialNumber}</td>
                  <td>{cert.learnerName}</td>
                  <td>{cert.courseTitle}</td>
                  <td>
                    <span className={`status status-${cert.status}`}>{cert.status}</span>
                  </td>
                  <td>{cert.issuedDateLocal}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="pagination">
            <button
              className="btn"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              Previous
            </button>
            <span>
              Page {page} of {totalPages} ({total} total)
            </span>
            <button
              className="btn"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </button>
          </div>
        </>
      )}
    </div>
  );
}

