const ACTOR_STORAGE_KEY = 'certAdmin.actorId';

export function getStoredActorId(): string | null {
  return localStorage.getItem(ACTOR_STORAGE_KEY);
}

export function storeActorId(id: string | null) {
  if (id === null) localStorage.removeItem(ACTOR_STORAGE_KEY);
  else localStorage.setItem(ACTOR_STORAGE_KEY, id);
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  const actorId = getStoredActorId();
  if (actorId) headers.set('X-Actor-Id', actorId);
  const res = await fetch(path, { ...init, headers });
  if (!res.ok) {
    let message = `Request failed (${res.status})`;
    try {
      const data = await res.json();
      if (data && typeof data.error === 'string') message = data.error;
    } catch {
      // ignore
    }
    throw new ApiError(res.status, message);
  }
  return res.json() as Promise<T>;
}
```

