import { useEffect, useState } from 'react';
import {
  Actor,
  errorMessage,
  fetchActors,
  getStoredActorId,
  storeActorId,
} from './api';
import { ActorSwitcher } from './components/ActorSwitcher';
import { BulkIssue } from './components/BulkIssue';
import { CertificateDetail } from './components/CertificateDetail';
import { CertificateList } from './components/CertificateList';

export default function App() {
  const [actors, setActors] = useState<Actor[]>([]);
  const [actorsLoading, setActorsLoading] = useState(true);
  const [actorsError, setActorsError] = useState<string | null>(null);
  const [actorId, setActorId] = useState<string | null>(null);
  const [selectedCertificateId, setSelectedCertificateId] = useState<number | null>(null);
  const [listRefreshToken, setListRefreshToken] = useState(0);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const list = await fetchActors();
        if (cancelled) return;
        setActors(list);
        setActorsError(null);

        const stored = getStoredActorId();
        const next =
          stored && list.some((actor) => actor.email === stored)
            ? stored
            : (list[0]?.email ?? null);
        storeActorId(next);
        setActorId(next);
      } catch (err) {
        if (!cancelled) setActorsError(errorMessage(err));
      } finally {
        if (!cancelled) setActorsLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const refreshList = () => setListRefreshToken((n) => n + 1);

  const handleChangeActor = (email: string) => {
    storeActorId(email);
    setActorId(email);
    setSelectedCertificateId(null);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Certificate Admin Console</h1>
        <ActorSwitcher
          actors={actors}
          actorId={actorId}
          loading={actorsLoading}
          error={actorsError}
          onChange={handleChangeActor}
        />
      </header>

      {actorId === null ? (
        <div className="placeholder">
          <p>Select an actor to continue.</p>
        </div>
      ) : (
        <main className="app-main">
          <section className="panel">
            <BulkIssue actorId={actorId} onIssued={refreshList} />
          </section>
          <section className="panel">
            <CertificateList
              actorId={actorId}
              refreshToken={listRefreshToken}
              onSelectCertificate={setSelectedCertificateId}
            />
          </section>
        </main>
      )}

      {selectedCertificateId !== null && (
        <CertificateDetail
          certificateId={selectedCertificateId}
          onClose={() => setSelectedCertificateId(null)}
          onRevoked={() => {
            setSelectedCertificateId(null);
            refreshList();
          }}
        />
      )}
    </div>
  );
}

import { Actor } from '../api';

interface Props {
  actors: Actor[];
  actorId: string | null;
  loading: boolean;
  error: string | null;
  onChange: (email: string) => void;
}

export function ActorSwitcher({ actors, actorId, loading, error, onChange }: Props) {
  if (loading) {
    return <span className="actor-loading">Loading actors…</span>;
  }

  if (error) {
    return (
      <span className="actor-error" role="alert">
        Actors unavailable: {error}
      </span>
    );
  }

  return (
    <label className="actor-switcher">
      <span className="actor-label">Actor</span>
      <select value={actorId ?? ''} onChange={(e) => onChange(e.target.value)}>
        <option value="" disabled>
          Select an actor
        </option>
        {actors.map((actor) => (
          <option key={actor.email} value={actor.email}>
            {actor.email} ({actor.tenant})
          </option>
        ))}
      </select>
    </label>
  );
}

import { useEffect, useState } from 'react';
import {
  CertificateListItem,
  errorMessage,
  exportCsv,
  fetchCertificates,
} from '../api';

interface Props {
  actorId: string;
  refreshToken: number;
  onSelectCertificate: (id: number) => void;
}

const SORT_OPTIONS: { value: string; label: string }[] = [
  { value: 'issueDate', label: 'Issue date' },
  { value: 'learnerName', label: 'Learner name' },
  { value: 'serial', label: 'Serial number' },
  { value: 'courseTitle', label: 'Course' },
];

export function CertificateList({ actorId, refreshToken, onSelectCertificate }: Props) {
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState('issueDate');
  const [order, setOrder] = useState<'asc' | 'desc'>('desc');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const [items, setItems] = useState<CertificateListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [retryToken, setRetryToken] = useState(0);

  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState<string | null>(null);

  // Debounce the search input before it hits the list query.
  useEffect(() => {
    const timer = setTimeout(() => {
      setSearch(searchInput);
      setPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchInput]);

  useEffect(() => {
    if (!actorId) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchCertificates({ search, sort, order, page, pageSize })
      .then((data) => {
        if (cancelled) return;
        setItems(data.items);
        setTotal(data.total);
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(errorMessage(err));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [actorId, refreshToken, retryToken, search, sort, order, page, pageSize]);

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  const handleExport = async () => {
    setExporting(true);
    setExportError(null);
    try {
      await exportCsv(search, sort, order);
    } catch (err) {
      setExportError(errorMessage(err));
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className="certificate-list">
      <div className="list-header">
        <h2>Certificates</h2>
        <button className="btn" onClick={handleExport} disabled={exporting}>
          {exporting ? 'Exporting…' : 'Export CSV'}
        </button>
      </div>

      <div className="controls">
        <input
          type="search"
          className="search-input"
          placeholder="Search learner name or serial"
          value={searchInput}
          onChange={(e) => setSearchInput(e.target.value)}
        />
        <select
          value={sort}
          onChange={(e) => {
            setSort(e.target.value);
            setPage(1);
          }}
        >
          {SORT_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              Sort: {option.label}
            </option>
          ))}
        </select>
        <select
          value={order}
          onChange={(e) => {
            setOrder(e.target.value as 'asc' | 'desc');
            setPage(1);
          }}
        >
          <option value="desc">Descending</option>
          <option value="asc">Ascending</option>
        </select>
        <select
          value={pageSize}
          onChange={(e) => {
            setPageSize(Number(e.target.value));
            setPage(1);
          }}
        >
          <option value={20}>20 / page</option>
          <option value={50}>50 / page</option>
          <option value={100}>100 / page</option>
        </select>
      </div>

      {exportError && (
        <div className="error-banner" role="alert">
          Export failed: {exportError}
        </div>
      )}

      {loading ? (
        <div className="state">Loading certificates…</div>
      ) : error ? (
        <div className="state error" role="alert">
          <p>{error}</p>
          <button className="btn" onClick={() => setRetryToken((n) => n + 1)}>
            Retry
          </button>
        </div>
      ) : items.length === 0 ? (
        <div className="state">No certificates found.</div>
      ) : (
        <>
          <table className="cert-table">
            <thead>
              <tr>
                <th>Serial</th>
                <th>Learner</th>
                <th>Course</th>
                <th>Status</th>
                <th>Issued (local)</th>
              </tr>
            </thead>
            <tbody>
              {items.map((cert) => (
                <tr
                  key={cert.id}
                  className="clickable"
                  onClick={() => onSelectCertificate(cert.id)}
                >
                  <td>{cert.serialNumber}</td>
                  <td>{cert.learnerName}</td>
                  <td>{cert.courseTitle}</td>
                  <td>
                    <span className={`status status-${cert.status}`}>{cert.status}</span>
                  </td>
                  <td>{cert.issuedDateLocal}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="pagination">
            <button
              className="btn"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              Previous
            </button>
            <span>
              Page {page} of {totalPages} ({total} total)
            </span>
            <button
              className="btn"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </button>
          </div>
        </>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  BulkIssueResult,
  Course,
  bulkIssue,
  errorMessage,
  fetchCourses,
} from '../api';

interface Props {
  actorId: string;
  onIssued: () => void;
}

export function BulkIssue({ actorId, onIssued }: Props) {
  const [courses, setCourses] = useState<Course[]>([]);
  const [coursesLoading, setCoursesLoading] = useState(true);
  const [coursesError, setCoursesError] = useState<string | null>(null);

  const [courseId, setCourseId] = useState<number | null>(null);
  const [idempotencyKey, setIdempotencyKey] = useState<string | null>(null);
  const [inFlight, setInFlight] = useState(false);
  const [result, setResult] = useState<BulkIssueResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setCoursesLoading(true);
    setCoursesError(null);
    fetchCourses()
      .then((list) => {
        if (cancelled) return;
        setCourses(list);
        setCoursesLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        setCoursesError(errorMessage(err));
        setCoursesLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [actorId]);

  const selectCourse = (id: number) => {
    setCourseId(id);
    setIdempotencyKey(crypto.randomUUID());
    setResult(null);
    setError(null);
  };

  const handleIssue = async () => {
    if (courseId === null || inFlight) return;
    // Reuse the key across retries of the same operation; it was generated
    // when the course was selected and only regenerates on course change.
    const key = idempotencyKey ?? crypto.randomUUID();
    if (idempotencyKey === null) setIdempotencyKey(key);

    setInFlight(true);
    setError(null);
    try {
      const res = await bulkIssue(courseId, key);
      setResult(res);
      onIssued();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setInFlight(false);
    }
  };

  return (
    <div className="bulk-issue">
      <h2>Bulk issue</h2>

      {coursesLoading ? (
        <div className="state">Loading courses…</div>
      ) : coursesError ? (
        <div className="state error" role="alert">
          {coursesError}
        </div>
      ) : (
        <>
          <div className="controls">
            <select
              value={courseId ?? ''}
              onChange={(e) => selectCourse(Number(e.target.value))}
            >
              <option value="" disabled>
                Select a course
              </option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title} (#{course.id})
                </option>
              ))}
            </select>
            <button
              className="btn btn-primary"
              disabled={courseId === null || inFlight}
              onClick={handleIssue}
            >
              {inFlight ? 'Issuing…' : 'Issue all eligible'}
            </button>
          </div>

          {error && (
            <div className="error-banner" role="alert">
              Bulk issue failed: {error}
            </div>
          )}

          {result && (
            <div className="bulk-result">
              <div className="summary">
                Issued: {result.summary.issued} · Skipped: {result.summary.skipped} · Failed:{' '}
                {result.summary.failed}
              </div>
              {result.outcomes.length > 0 ? (
                <table className="cert-table outcomes">
                  <thead>
                    <tr>
                      <th>Learner</th>
                      <th>Status</th>
                      <th>Reason</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.outcomes.map((outcome) => (
                      <tr key={outcome.learnerId}>
                        <td>{outcome.learnerName}</td>
                        <td>
                          <span className={`status status-${outcome.status}`}>
                            {outcome.status}
                          </span>
                        </td>
                        <td>{outcome.reason ?? '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="state">No eligible learners.</div>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  CertificateDetail as CertificateDetailData,
  errorMessage,
  fetchCertificate,
  revokeCertificate,
} from '../api';

interface Props {
  certificateId: number;
  onClose: () => void;
  onRevoked: () => void;
}

export function CertificateDetail({ certificateId, onClose, onRevoked }: Props) {
  const [data, setData] = useState<CertificateDetailData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [revoking, setRevoking] = useState(false);
  const [revokeError, setRevokeError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    setRevokeError(null);
    fetchCertificate(certificateId)
      .then((detail) => {
        if (cancelled) return;
        setData(detail);
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(errorMessage(err));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [certificateId]);

  const handleRevoke = async () => {
    if (!data) return;
    if (!window.confirm(`Revoke certificate ${data.serialNumber} for ${data.learnerName}?`)) {
      return;
    }
    setRevoking(true);
    setRevokeError(null);
    try {
      await revokeCertificate(data.id);
      setData({ ...data, status: 'revoked' });
      onRevoked();
    } catch (err) {
      setRevokeError(errorMessage(err));
    } finally {
      setRevoking(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Certificate detail</h2>
          <button className="btn" onClick={onClose} aria-label="Close">
            Close
          </button>
        </div>

        {loading ? (
          <div className="state">Loading…</div>
        ) : error ? (
          <div className="state error" role="alert">
            {error}
          </div>
        ) : data ? (
          <div className="detail">
            <dl className="detail-list">
              <dt>Serial</dt>
              <dd>{data.serialNumber}</dd>
              <dt>Learner</dt>
              <dd>{data.learnerName}</dd>
              <dt>Course</dt>
              <dd>{data.courseTitle}</dd>
              <dt>Status</dt>
              <dd>
                <span className={`status status-${data.status}`}>{data.status}</span>
              </dd>
              <dt>Issued (local)</dt>
              <dd>{data.issuedAtLocal}</dd>
              {data.revokedAtLocal && (
                <>
                  <dt>Revoked (local)</dt>
                  <dd>{data.revokedAtLocal}</dd>
                </>
              )}
            </dl>

            {data.status !== 'revoked' && (
              <button
                className="btn btn-danger"
                onClick={handleRevoke}
                disabled={revoking}
              >
                {revoking ? 'Revoking…' : 'Revoke'}
              </button>
            )}

            {revokeError && (
              <div className="error-banner" role="alert">
                Revoke failed: {revokeError}
              </div>
            )}
          </div>
        ) : null}
      </div>
    </div>
  );
}

:root {
  --border: #e2e4e8;
  --text: #1f2328;
  --muted: #636c76;
  --bg: #f6f7f9;
  --panel: #ffffff;
  --accent: #1a6fb0;
  --accent-dark: #145a8f;
  --danger: #b42318;
  --ok: #1a7f37;
  --warn: #9a6700;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family:
    system-ui,
    -apple-system,
    "Segoe UI",
    Roboto,
    "Helvetica Neue",
    sans-serif;
  color: var(--text);
  background: var(--bg);
}

.app {
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}

.app-header h1 {
  font-size: 1.35rem;
  margin: 0;
}

.app-main {
  display: grid;
  gap: 20px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
}

.panel h2 {
  margin: 0 0 12px;
  font-size: 1.05rem;
}

.placeholder {
  padding: 48px 20px;
  text-align: center;
  color: var(--muted);
  background: var(--panel);
  border: 1px dashed var(--border);
  border-radius: 10px;
}

.actor-switcher {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
}

.actor-label {
  color: var(--muted);
}

.actor-loading,
.actor-error {
  font-size: 0.9rem;
  color: var(--muted);
}

.actor-error {
  color: var(--danger);
}

.controls {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.search-input {
  flex: 1;
  min-width: 220px;
}

input,
select {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  font-size: 0.9rem;
  color: var(--text);
}

input:focus,
select:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
}

.btn {
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  font-size: 0.9rem;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  background: #f0f1f3;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-dark);
}

.btn-danger {
  background: #fff;
  border-color: var(--danger);
  color: var(--danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger);
  color: #fff;
}

.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.state {
  padding: 28px 12px;
  text-align: center;
  color: var(--muted);
}

.state.error {
  color: var(--danger);
}

.state.error p {
  margin: 0 0 12px;
}

.error-banner {
  margin: 10px 0;
  padding: 10px 12px;
  border: 1px solid #f1b8b3;
  border-radius: 6px;
  background: #fdf3f2;
  color: var(--danger);
  font-size: 0.9rem;
}

.cert-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.cert-table th,
.cert-table td {
  text-align: left;
  padding: 9px 10px;
  border-bottom: 1px solid var(--border);
}

.cert-table th {
  color: var(--muted);
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.cert-table tbody tr.clickable {
  cursor: pointer;
}

.cert-table tbody tr.clickable:hover {
  background: #f4f8fb;
}

.status {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: capitalize;
}

.status-active,
.status-issued {
  background: #e7f6ec;
  color: var(--ok);
}

.status-revoked {
  background: #f1f1f3;
  color: var(--muted);
}

.status-skipped {
  background: #fdf3dd;
  color: var(--warn);
}

.status-failed {
  background: #fdecea;
  color: var(--danger);
}

.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  font-size: 0.9rem;
  color: var(--muted);
}

.bulk-result {
  margin-top: 14px;
}

.bulk-result .summary {
  margin-bottom: 10px;
  font-weight: 600;
}

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 20, 25, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 10;
}

.modal {
  background: #fff;
  border-radius: 10px;
  padding: 20px;
  width: 100%;
  max-width: 480px;
  max-height: 90vh;
  overflow: auto;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.modal-header h2 {
  margin: 0;
  font-size: 1.05rem;
}

.detail-list {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 8px 12px;
  margin: 0 0 18px;
  font-size: 0.9rem;
}

.detail-list dt {
  color: var(--muted);
}

.detail-list dd {
  margin: 0;
  overflow-wrap: anywhere;
}
